void af_rf_quantize(const float x[5], int8_t q[5]) {
  for(int i=0;i<5;i++) {
    long v=lrintf(x[i]/input_scales[i]+input_zero_points[i]);
    if(v < -128) { v=-128; }
    if(v > 127) { v=127; }
    q[i]=(int8_t)v;
  }
}
af_rf_result_t af_rf_predict_int8(const int8_t q[5]) {
  uint32_t score=0; uint16_t comparisons=0;
  for(int t=0;t<80;t++) { int16_t n=(int16_t)tree_roots[t];
    while(!nodes[n].is_leaf) { const node_t *p=&nodes[n]; n=q[p->feature]<=p->threshold?p->left:p->right; comparisons++; }
    score+=nodes[n].probability;
  }
  af_rf_result_t out={(uint16_t)score,comparisons}; return out;
}
af_rf_result_t af_rf_predict(const float x[5]) { int8_t q[5]; af_rf_quantize(x,q); return af_rf_predict_int8(q); }
int af_rf_predict_label(const float x[5]) { return af_rf_predict(x).score >= 10240U; }
size_t af_rf_flash_bytes(void) { return sizeof(nodes)+sizeof(tree_roots)+sizeof(input_scales)+sizeof(input_zero_points); }
size_t af_rf_working_ram_bytes(void) { return 5U*sizeof(int8_t)+sizeof(af_rf_result_t)+sizeof(uint32_t); }
